def ichol(A):
    """Inputs:
    A : Matrix, 2d array M * M
    Outputs:
    A : Matrix, 2d array M * M (modified in-place to contain incomplete Cholesky factor)
    """
    M = A.shape[0]
    for i in range(M):
        sum_val = 0.0
        for k in range(i):
            sum_val += A[i, k] ** 2
        diag_val = A[i, i] - sum_val
        if diag_val <= 0:
            diag_val = 1e-10
        A[i, i] = np.sqrt(diag_val)
        for j in range(i + 1, M):
            if A[j, i] != 0:
                sum_val = 0.0
                for k in range(i):
                    sum_val += A[i, k] * A[j, k]
                A[j, i] = (A[j, i] - sum_val) / A[i, i]
            else:
                A[j, i] = 0.0
        for j in range(i):
            A[j, i] = 0.0
    return A
